node -e "
const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
const text = data.toString('utf-8');

// Find table schema info
const schemaIdx = text.indexOf('CREATE TABLE');
if (schemaIdx !== -1) {
  const end = Math.min(text.length, schemaIdx + 500);
  const snippet = data.slice(schemaIdx, end).toString('utf-8').replace(/[^\x20-\x7E\n\r\t]/g, ' ');
  console.log('Schema:', snippet);
}

// Also search for all CREATE TABLE
let pos = 0;
while ((pos = text.indexOf('CREATE TABLE', pos)) !== -1) {
  const end = Math.min(text.length, pos + 300);
  const snippet = data.slice(pos, end).toString('utf-8').replace(/[^\x20-\x7E\n\r\t]/g, ' ');
  console.log('---');
  console.log(snippet.split(' ').filter(s => s.trim()).slice(0, 30).join(' '));
  pos += 12;
}
"

