const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
const text = data.toString('utf-8');

// Find Daniel Ortiz and extract surrounding context more carefully
const idx = text.indexOf('Daniel Ortiz');
const start = Math.max(0, idx - 100);
const end = Math.min(text.length, idx + 200);
const snippet = data.slice(start, end).toString('latin1');
// Print hex + ascii for better parsing
for (let i = idx - 50; i < idx + 150; i++) {
  const b = data[i];
  if (b >= 32 && b <= 126) process.stdout.write(String.fromCharCode(b));
  else process.stdout.write('|');
}
console.log();
"
